// Every JSON file the app ships must parse, carry content, and still have the
// columns the scoring reads.
//
// These files are generated by scripts/build_app_data.py out of the published
// tables, and nothing else checks them. TypeScript cannot see inside a file
// that is fetched at runtime, so a half-written file or a renamed column does
// not break the build — it breaks the score, silently, in front of whoever is
// holding the phone. This is the cheapest place to catch that.
import { readFileSync, readdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const dataDir = join(root, 'public', 'data')
let failed = 0
const fail = (msg) => {
  console.error(`FAIL  ${msg}`)
  failed++
}

const files = readdirSync(dataDir).filter((f) => f.endsWith('.json')).sort()
if (files.length === 0) {
  console.error(`FAIL  no JSON files in public/data. The app has nothing to score with.`)
  process.exit(1)
}

/** Parsed content, so the district check below can reuse it. */
const parsed = new Map()

for (const file of files) {
  const path = join(dataDir, file)
  const raw = readFileSync(path, 'utf8')
  if (raw.trim().length === 0) {
    fail(`public/data/${file} is empty.`)
    continue
  }
  let value
  try {
    value = JSON.parse(raw)
  } catch (err) {
    fail(`public/data/${file} does not parse: ${err.message}`)
    continue
  }
  // "Non-empty" has to mean more than a byte count: `{}` and `[]` parse
  // cleanly and would sail through, then produce an empty map and a score
  // built on nothing.
  const size = Array.isArray(value)
    ? value.length
    : value && typeof value === 'object'
      ? Object.keys(value).length
      : value === null
        ? 0
        : 1
  if (size === 0) {
    fail(`public/data/${file} parses but holds no entries.`)
    continue
  }
  parsed.set(file, value)
  const kb = (raw.length / 1024).toFixed(1)
  console.log(`  ok  ${file.padEnd(18)} ${String(size).padStart(5)} top-level ${Array.isArray(value) ? 'items' : 'keys '}  ${kb.padStart(7)} KB`)
}

// --- The columns src/lib/risk.ts reads off each district ------------------
// assessRoute() pools these counts to work out whether a corridor is unusually
// bad for the way you are travelling. If one goes missing the arithmetic still
// runs: undefined makes the pooled share NaN, and the app shows "NaN% of
// casualties here" rather than failing loudly.
const REQUIRED_DISTRICT_FIELDS = [
  'pedestrianCasualties',
  'riderCasualties',
  'otherCasualties',
  'totalCasualties',
]

const districts = parsed.get('districts.json')
if (!districts) {
  fail('public/data/districts.json is missing or unreadable; the score cannot be computed without it.')
} else if (!Array.isArray(districts.districts) || districts.districts.length === 0) {
  fail('public/data/districts.json has no districts array.')
} else {
  let bad = 0
  for (const [i, d] of districts.districts.entries()) {
    const name = d?.name ?? `index ${i}`
    for (const field of REQUIRED_DISTRICT_FIELDS) {
      if (!Number.isFinite(d?.[field])) {
        fail(`districts.json: ${name} has no usable ${field} (got ${JSON.stringify(d?.[field])}).`)
        bad++
      }
    }
  }
  if (bad === 0) {
    console.log(
      `  ok  districts.json    ${districts.districts.length} districts carry ${REQUIRED_DISTRICT_FIELDS.join(', ')}`,
    )
  }
}

if (failed) {
  console.error(`\n${failed} data problem${failed === 1 ? '' : 's'}. Rebuild public/data before shipping.`)
  process.exit(1)
}
console.log(`\nPASS  data integrity (${files.length} files)`)
